create table if not exists public.mz_benefit_partners(id uuid primary key default gen_random_uuid(), name text not null, description text, logo_url text, contact jsonb not null default '{}'::jsonb, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.mz_benefits(id uuid primary key default gen_random_uuid(), partner_id uuid references public.mz_benefit_partners(id) on delete cascade, title text not null, description text, discount_text text, terms text, starts_at timestamptz, ends_at timestamptz, redemption_limit int, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.mz_benefit_redemptions(id uuid primary key default gen_random_uuid(), benefit_id uuid not null references public.mz_benefits(id) on delete cascade, user_id uuid not null references auth.users(id), code text not null, status text not null default 'issued', issued_at timestamptz not null default now(), redeemed_at timestamptz, unique(benefit_id,user_id));
alter table public.mz_benefit_partners enable row level security; alter table public.mz_benefits enable row level security; alter table public.mz_benefit_redemptions enable row level security;
create policy "partners public" on public.mz_benefit_partners for select using(active);
create policy "benefits public" on public.mz_benefits for select using(active and (ends_at is null or ends_at>now()));
create policy "own redemptions" on public.mz_benefit_redemptions for all using(user_id=auth.uid()) with check(user_id=auth.uid());
